    /// <summary>
    /// Full, immutable definition of a custom strategy.
    /// <code>
    /// factor = clamp(curve(axis(screen) / axis(reference)) × multiplier × AR, minFactor, maxFactor)
    /// dp     = transform(clampValue(base × factor, minValue, maxValue))
    /// </code>
    /// </summary>
    public sealed class ScalingConfig
    {
        public static readonly ScalingConfig Default = new ScalingConfig();

        public ScalingConfig(
            ReferenceScreen? reference = null, ScalingAxis axis = ScalingAxis.SmallestWidth, ScalingCurve? curve = null,
            float multiplier = 1f, float? minFactor = null, float? maxFactor = null,
            float? minValue = null, float? maxValue = null, bool aspectRatio = false, float? sensitivity = null,
            FontScalePolicy? fontScale = null, bool ignoreMultiWindow = false, ValueTransform? transform = null,
            IEnumerable<ScalingRule>? rules = null, Formula? formula = null)
        {
            if (!float.IsFinite(multiplier)) throw new ArgumentException("multiplier must be finite");
            FiniteOrNull(minFactor, "minFactor");
            FiniteOrNull(maxFactor, "maxFactor");
            FiniteOrNull(minValue, "minValue");
            FiniteOrNull(maxValue, "maxValue");
            FiniteOrNull(sensitivity, "sensitivity");
            Reference = reference ?? ReferenceScreen.Default;
            Axis = axis;
            Curve = curve ?? ScalingCurve.Linear;
            Multiplier = multiplier;
            MinFactor = minFactor; MaxFactor = maxFactor;
            MinValue = minValue; MaxValue = maxValue;
            AspectRatio = aspectRatio;
            Sensitivity = sensitivity;
            FontScale = fontScale ?? FontScalePolicy.Follow;
            IgnoreMultiWindow = ignoreMultiWindow;
            Transform = formula != null ? null : transform;
            Formula = formula;
            Rules = rules?.ToArray() ?? Array.Empty<ScalingRule>();
        }

        public ReferenceScreen Reference { get; }
        public ScalingAxis Axis { get; }
        public ScalingCurve Curve { get; }
        public float Multiplier { get; }
        public float? MinFactor { get; }
        public float? MaxFactor { get; }
        public float? MinValue { get; }
        public float? MaxValue { get; }
        public bool AspectRatio { get; }
        public float? Sensitivity { get; }
        public FontScalePolicy FontScale { get; }
        public bool IgnoreMultiWindow { get; }
        /// <summary>Code-only per-value hook (not serializable).</summary>
        public ValueTransform? Transform { get; }
        /// <summary>Per-value text formula (JSON-serializable); takes the place of <see cref="Transform"/>.</summary>
        public Formula? Formula { get; }
        public IReadOnlyList<ScalingRule> Rules { get; }

        /// <summary>True when some path depends on the value itself (not only on the screen).</summary>
        public bool IsValueDependent =>
            MinValue.HasValue || MaxValue.HasValue || Transform != null || (Formula != null && !Formula.IsProportional) ||
            Rules.Any(r => r.Patch.IsValueDependent);

        /// <summary>
        /// Cross-field checks for a declared config (the base and each rule on top of it).
        /// Rules combined at runtime never throw: when bounds cross, the max bound wins.
        /// </summary>
        public ScalingConfig Validate()
        {
            if (MinFactor.HasValue && MaxFactor.HasValue && MinFactor.Value > MaxFactor.Value)
                throw new ArgumentException("minFactor must be <= maxFactor");
            if (MinValue.HasValue && MaxValue.HasValue && MinValue.Value > MaxValue.Value)
                throw new ArgumentException("minValue must be <= maxValue");
            foreach (var r in Rules) Apply(r.Patch).WithRules(Array.Empty<ScalingRule>()).Validate();
            return this;
        }

        /// <summary>Returns this config with <paramref name="patch"/> applied.</summary>
        public ScalingConfig Apply(ScalingPatch patch) => new ScalingConfig(
            patch.Reference ?? Reference, patch.Axis ?? Axis, patch.Curve ?? Curve,
            patch.Multiplier ?? Multiplier, patch.MinFactor ?? MinFactor, patch.MaxFactor ?? MaxFactor,
            patch.MinValue ?? MinValue, patch.MaxValue ?? MaxValue, patch.AspectRatio ?? AspectRatio,
            patch.Sensitivity ?? Sensitivity, patch.FontScale ?? FontScale,
            patch.IgnoreMultiWindow ?? IgnoreMultiWindow,
            patch.Formula != null ? null : patch.Transform ?? Transform, Rules,
            patch.Transform != null && patch.Formula == null ? null : patch.Formula ?? Formula);

        /// <summary>Copy with the given fields replaced (pass only what changes).</summary>
        public ScalingConfig With(
            ReferenceScreen? reference = null, ScalingAxis? axis = null, ScalingCurve? curve = null,
            float? multiplier = null, bool? aspectRatio = null, FontScalePolicy? fontScale = null,
            bool? ignoreMultiWindow = null) => new ScalingConfig(
            reference ?? Reference, axis ?? Axis, curve ?? Curve, multiplier ?? Multiplier,
            MinFactor, MaxFactor, MinValue, MaxValue, aspectRatio ?? AspectRatio, Sensitivity,
            fontScale ?? FontScale, ignoreMultiWindow ?? IgnoreMultiWindow, Transform, Rules, Formula);

        public ScalingConfig WithFactorBounds(float? min, float? max) => new ScalingConfig(
            Reference, Axis, Curve, Multiplier, min, max, MinValue, MaxValue, AspectRatio, Sensitivity,
            FontScale, IgnoreMultiWindow, Transform, Rules, Formula);

        public ScalingConfig WithValueBounds(float? min, float? max) => new ScalingConfig(
            Reference, Axis, Curve, Multiplier, MinFactor, MaxFactor, min, max, AspectRatio, Sensitivity,
            FontScale, IgnoreMultiWindow, Transform, Rules, Formula);

        public ScalingConfig WithAspectRatio(bool enabled, float? sensitivity) => new ScalingConfig(
            Reference, Axis, Curve, Multiplier, MinFactor, MaxFactor, MinValue, MaxValue, enabled, sensitivity,
            FontScale, IgnoreMultiWindow, Transform, Rules, Formula);

        public ScalingConfig WithTransform(ValueTransform? transform) => new ScalingConfig(
            Reference, Axis, Curve, Multiplier, MinFactor, MaxFactor, MinValue, MaxValue, AspectRatio, Sensitivity,
            FontScale, IgnoreMultiWindow, transform, Rules, null);

        public ScalingConfig WithFormula(Formula? formula) => new ScalingConfig(
            Reference, Axis, Curve, Multiplier, MinFactor, MaxFactor, MinValue, MaxValue, AspectRatio, Sensitivity,
            FontScale, IgnoreMultiWindow, null, Rules, formula);

        public ScalingConfig WithRules(IEnumerable<ScalingRule> rules) => new ScalingConfig(
            Reference, Axis, Curve, Multiplier, MinFactor, MaxFactor, MinValue, MaxValue, AspectRatio, Sensitivity,
            FontScale, IgnoreMultiWindow, Transform, rules, Formula);

        private static void FiniteOrNull(float? v, string name)
        {
            if (v.HasValue && !float.IsFinite(v.Value)) throw new ArgumentException($"{name} must be finite");
        }
    }
}

// ── CustomExpression.cs ──
namespace AppDimensGames.Custom
{
    /// <summary>
    /// Free-form formula written as text, so it can live in JSON and behaves the same on every
    /// platform. Booleans are numbers (true = 1, false = 0; non-zero is true).
    /// <para>Operators: <c>+ - * / % ^</c> (<c>^</c> is power, right-associative; <c>%</c> keeps the sign of
    /// the dividend), <c>== != &lt; &lt;= &gt; &gt;=</c>, <c>&amp;&amp; || !</c>, <c>cond ? a : b</c>, parentheses.</para>
    /// <para>Functions: <c>min(a, b, …)</c>, <c>max(a, b, …)</c>, <c>clamp(x, lo, hi)</c>, <c>pow</c>, <c>sqrt</c>,
    /// <c>ln</c>/<c>log</c> (natural), <c>log10</c>, <c>log2</c>, <c>exp</c>, <c>abs</c>, <c>sign</c>, <c>floor</c>,
    /// <c>ceil</c>, <c>round</c> (half up), <c>lerp(a, b, t)</c>, <c>step(edge, x)</c>, <c>smoothstep(e0, e1, x)</c>.</para>
    /// <para>Variables: <see cref="ScreenVariables"/>; curves add <c>ratio axis ref refWidth refHeight</c>;
    /// value formulas add <c>base scaled factor</c>.</para>
    /// </summary>
    public sealed class ScalingExpression : IEquatable<ScalingExpression>
    {
        public static readonly IReadOnlyCollection<string> ScreenVariables = new HashSet<string>
        {
            "sw", "width", "height", "shortSide", "longSide", "diagonal", "perimeter", "aspectRatio",
            "density", "fontScale", "landscape", "portrait", "multiWindow",
            "phone", "tablet", "desktop", "tv", "watch", "car", "vr", "pi", "e",
        };

        public static readonly IReadOnlyCollection<string> CurveVariables =
            new HashSet<string>(ScreenVariables.Concat(new[] { "ratio", "axis", "ref", "refWidth", "refHeight" }));

        public static readonly IReadOnlyCollection<string> FormulaVariables =
            new HashSet<string>(CurveVariables.Concat(new[] { "base", "scaled", "factor" }));

        private readonly Node _root;

        private ScalingExpression(string source, Node root)
        {
            Source = source;
            _root = root;
        }

        public string Source { get; }

        /// <summary>Parses <paramref name="source"/>; every identifier must be in <paramref name="allowed"/>.</summary>
        public static ScalingExpression Parse(string source, IReadOnlyCollection<string>? allowed = null)
        {
            var root = new Parser(source ?? throw new ArgumentNullException(nameof(source)), allowed ?? FormulaVariables).ParseAll();
            var expression = new ScalingExpression(source, root);
            expression.BaseCoefficient = Coefficient(source, root);
            return expression;
        }

        /// <summary>Evaluates with a name → value lookup.</summary>
        public double Evaluate(Func<string, double> vars) => _root.Eval(vars);

        /// <summary>
        /// Non-null when the whole formula is <c>base</c>, <c>base * E</c> or <c>E * base</c> and <c>E</c> reads no
        /// value variable (<c>base</c>, <c>scaled</c>, <c>factor</c>). Such a formula is a pure screen factor, so
        /// strategies evaluate <c>E</c> once per window and skip the per-value cache (same result, bit for bit).
        /// <para>PT Não nulo quando a fórmula é <c>base</c>, <c>base * E</c> ou <c>E * base</c> e <c>E</c> não lê
        /// variáveis de valor: vira um fator só da tela, calculado uma vez por janela (mesmo resultado).</para>
        /// </summary>
        internal ScalingExpression? BaseCoefficient { get; private set; }

        private static readonly HashSet<string> ValueVariables = new HashSet<string> { "base", "scaled", "factor" };

        private static ScalingExpression? Coefficient(string source, Node root)
        {
            Node? coefficient = null;
            if (IsBase(root)) coefficient = new Num(1);
            else if (root is Binary b && b.Op == "*")
            {
                if (IsBase(b.A) && !b.B.Reads(ValueVariables)) coefficient = b.B;
                else if (IsBase(b.B) && !b.A.Reads(ValueVariables)) coefficient = b.A;
            }
            return coefficient == null ? null : new ScalingExpression(source, coefficient);
        }

        private static bool IsBase(Node n) => n is Var v && v.Name == "base";

        /// <summary>Variable lookup for <paramref name="screen"/> plus the strategy context.</summary>
        public static Func<string, double> Variables(ScreenSnapshot screen, float ratio, float axisDp, float refDp,
            ReferenceScreen reference, float baseValue = float.NaN, float scaled = float.NaN, float factor = float.NaN) => name =>
        {
            switch (name)
            {
                case "sw": return screen.SmallestWidthDp;
                case "width": return screen.WidthDp;
                case "height": return screen.HeightDp;
                case "shortSide": return screen.MinDp;
                case "longSide": return screen.MaxDp;
                case "diagonal": return screen.Read(ScalingAxis.Diagonal);
                case "perimeter": return screen.Read(ScalingAxis.Perimeter);
                case "aspectRatio": return screen.AspectRatio;
                case "density": return screen.Density;
                case "fontScale": return screen.FontScale;
                case "landscape": return screen.IsLandscape ? 1 : 0;
                case "portrait": return screen.IsLandscape ? 0 : 1;
                case "multiWindow": return screen.IsMultiWindow ? 1 : 0;
                case "phone": return screen.Device == DeviceClass.Phone ? 1 : 0;
                case "tablet": return screen.Device == DeviceClass.Tablet ? 1 : 0;
                case "desktop": return screen.Device == DeviceClass.Desktop ? 1 : 0;
                case "tv": return screen.Device == DeviceClass.Tv ? 1 : 0;
                case "watch": return screen.Device == DeviceClass.Watch ? 1 : 0;
                case "car": return screen.Device == DeviceClass.Car ? 1 : 0;
                case "vr": return screen.Device == DeviceClass.Vr ? 1 : 0;
                case "pi": return Math.PI;
                case "e": return Math.E;
                case "ratio": return ratio;
                case "axis": return axisDp;
                case "ref": return refDp;
                case "refWidth": return reference.Width;
                case "refHeight": return reference.Height;
                case "base": return baseValue;
                case "scaled": return scaled;
                case "factor": return factor;
                default: return double.NaN;
            }
        };

        public bool Equals(ScalingExpression? other) => other != null && other.Source == Source;
        public override bool Equals(object? obj) => Equals(obj as ScalingExpression);
        public override int GetHashCode() => Source.GetHashCode();
        public override string ToString() => Source;

        // ── AST ─────────────────────────────────────────────────────────────

        private abstract class Node
        {
            public abstract double Eval(Func<string, double> v);

            /// <summary>True when this subtree reads any of <paramref name="names"/>.</summary>
            public abstract bool Reads(ISet<string> names);
        }

        private sealed class Num : Node
        {
            private readonly double _value;
            public Num(double value) { _value = value; }
            public override double Eval(Func<string, double> v) => _value;
            public override bool Reads(ISet<string> names) => false;
        }

        private sealed class Var : Node
        {
            private readonly string _name;
            public Var(string name) { _name = name; }
            public string Name => _name;
            public override double Eval(Func<string, double> v) => v(_name);
            public override bool Reads(ISet<string> names) => names.Contains(_name);
        }

        private sealed class Unary : Node
        {
            private readonly char _op;
            private readonly Node _a;
            public Unary(char op, Node a) { _op = op; _a = a; }
            public override bool Reads(ISet<string> names) => _a.Reads(names);

            public override double Eval(Func<string, double> v)
            {
                var x = _a.Eval(v);
                return _op == '-' ? -x : (x != 0 ? 0 : 1);
            }
        }

        private sealed class Binary : Node
        {
            private readonly string _op;
            private readonly Node _a, _b;
            public Binary(string op, Node a, Node b) { _op = op; _a = a; _b = b; }
            public string Op => _op;
            public Node A => _a;
            public Node B => _b;
            public override bool Reads(ISet<string> names) => _a.Reads(names) || _b.Reads(names);

            public override double Eval(Func<string, double> v)
            {
                if (_op == "&&") return _a.Eval(v) != 0 && _b.Eval(v) != 0 ? 1 : 0;
                if (_op == "||") return _a.Eval(v) != 0 || _b.Eval(v) != 0 ? 1 : 0;
                var x = _a.Eval(v);
                var y = _b.Eval(v);
                switch (_op)
                {
                    case "+": return x + y;
                    case "-": return x - y;
                    case "*": return x * y;
                    case "/": return x / y;
                    case "%": return x % y; // truncated: keeps the sign of the dividend
                    case "^": return Math.Pow(x, y);
                    case "==": return x == y ? 1 : 0;
                    case "!=": return x != y ? 1 : 0;
                    case "<": return x < y ? 1 : 0;
                    case "<=": return x <= y ? 1 : 0;
                    case ">": return x > y ? 1 : 0;
                    default: return x >= y ? 1 : 0;
                }
            }
        }

        private sealed class Ternary : Node
        {
            private readonly Node _c, _a, _b;
            public Ternary(Node c, Node a, Node b) { _c = c; _a = a; _b = b; }
            public override double Eval(Func<string, double> v) => _c.Eval(v) != 0 ? _a.Eval(v) : _b.Eval(v);
            public override bool Reads(ISet<string> names) => _c.Reads(names) || _a.Reads(names) || _b.Reads(names);
        }

        private sealed class Call : Node
        {
            private readonly string _name;
            private readonly Node[] _args;
            public Call(string name, Node[] args) { _name = name; _args = args; }
            public override bool Reads(ISet<string> names) => _args.Any(a => a.Reads(names));

            public override double Eval(Func<string, double> v)
            {
                var x = new double[_args.Length];
                for (var i = 0; i < x.Length; i++) x[i] = _args[i].Eval(v);
                switch (_name)
                {
                    case "min": return x.Min();
                    case "max": return x.Max();
                    case "clamp": return Math.Max(x[1], Math.Min(x[2], x[0]));
                    case "pow": return Math.Pow(x[0], x[1]);
                    case "sqrt": return Math.Sqrt(x[0]);
                    case "ln":
                    case "log": return Math.Log(x[0]);
                    case "log10": return Math.Log10(x[0]);
                    case "log2": return Math.Log(x[0]) / Math.Log(2);
                    case "exp": return Math.Exp(x[0]);
                    case "abs": return Math.Abs(x[0]);
                    case "sign": return double.IsNaN(x[0]) ? double.NaN : Math.Sign(x[0]);
                    case "floor": return Math.Floor(x[0]);
                    case "ceil": return Math.Ceiling(x[0]);
                    case "round": return Math.Floor(x[0] + 0.5);
                    case "lerp": return x[0] + (x[1] - x[0]) * x[2];
                    case "step": return x[1] < x[0] ? 0 : 1;
                    default:
                        var t = Math.Max(0, Math.Min(1, (x[2] - x[0]) / (x[1] - x[0])));
                        return t * t * (3 - 2 * t);
                }
            }
        }

        // ── Parser (recursive descent) ──────────────────────────────────────

        private sealed class Parser
        {
            private const int Many = int.MaxValue;

            private static readonly Dictionary<string, (int Min, int Max)> Arity = new Dictionary<string, (int, int)>
            {
                ["min"] = (1, Many), ["max"] = (1, Many), ["clamp"] = (3, 3), ["pow"] = (2, 2), ["sqrt"] = (1, 1),
                ["ln"] = (1, 1), ["log"] = (1, 1), ["log10"] = (1, 1), ["log2"] = (1, 1), ["exp"] = (1, 1),
                ["abs"] = (1, 1), ["sign"] = (1, 1), ["floor"] = (1, 1), ["ceil"] = (1, 1), ["round"] = (1, 1),
                ["lerp"] = (3, 3), ["step"] = (2, 2), ["smoothstep"] = (3, 3),
            };

            private static readonly string[] Comparisons = { "==", "!=", "<=", ">=", "<", ">" };

            private readonly string _src;
            private readonly IReadOnlyCollection<string> _allowed;
            private int _i;

            public Parser(string src, IReadOnlyCollection<string> allowed) { _src = src; _allowed = allowed; }

            public Node ParseAll()
            {
                if (string.IsNullOrWhiteSpace(_src)) throw Fail("empty expression");
                var n = Ternary();
                Ws();
                if (_i < _src.Length) throw Fail($"unexpected '{_src[_i]}'");
                return n;
            }

            private Node Ternary()
            {
                var c = Or();
                if (!Eat("?")) return c;
                var a = Ternary();
                if (!Eat(":")) throw Fail("expected ':'");
                return new Ternary(c, a, Ternary());
            }

            private Node Or()
            {
                var n = And();
                while (Eat("||")) n = new Binary("||", n, And());
                return n;
            }

            private Node And()
            {
                var n = Cmp();
                while (Eat("&&")) n = new Binary("&&", n, Cmp());
                return n;
            }

            private Node Cmp()
            {
                var n = Add();
                foreach (var op in Comparisons) if (Eat(op)) return new Binary(op, n, Add());
                return n;
            }

            private Node Add()
            {
                var n = Mul();
                while (true)
                {
                    if (Eat("+")) n = new Binary("+", n, Mul());
                    else if (Eat("-")) n = new Binary("-", n, Mul());
                    else return n;
                }
            }

            private Node Mul()
            {
                var n = UnaryNode();
                while (true)
                {
                    if (Eat("*")) n = new Binary("*", n, UnaryNode());
                    else if (Eat("/")) n = new Binary("/", n, UnaryNode());
                    else if (Eat("%")) n = new Binary("%", n, UnaryNode());
                    else return n;
                }
            }

            private Node UnaryNode()
            {
                if (Eat("-")) return new Unary('-', UnaryNode());
                if (Eat("+")) return UnaryNode();
                if (PeekIs("!") && !PeekIs("!=")) { Eat("!"); return new Unary('!', UnaryNode()); }
                return Power();
            }

            private Node Power()
            {
                var n = Primary();
                return Eat("^") ? new Binary("^", n, UnaryNode()) : n;
            }

            private Node Primary()
            {
                Ws();
                if (_i >= _src.Length) throw Fail("unexpected end");
                var c = _src[_i];
                if (c == '(')
                {
                    _i++;
                    var n = Ternary();
                    if (!Eat(")")) throw Fail("expected ')'");
                    return n;
                }
                if (char.IsDigit(c) || c == '.') return Number();
                if (char.IsLetter(c) || c == '_')
                {
                    var start = _i;
                    while (_i < _src.Length && (char.IsLetterOrDigit(_src[_i]) || _src[_i] == '_')) _i++;
                    var name = _src.Substring(start, _i - start);
                    if (Eat("(")) return CallNode(name, start);
                    if (name == "true") return new Num(1);
                    if (name == "false") return new Num(0);
                    if (!_allowed.Contains(name))
                    {
                        _i = start;
                        throw Fail($"unknown variable '{name}' (allowed: {string.Join(", ", _allowed.OrderBy(x => x, StringComparer.Ordinal))})");
                    }
                    return new Var(name);
                }
                throw Fail($"unexpected '{c}'");
            }

            private Node CallNode(string name, int start)
            {
                var args = new List<Node>();
                if (!Eat(")"))
                {
                    do args.Add(Ternary()); while (Eat(","));
                    if (!Eat(")")) throw Fail("expected ')'");
                }
                if (!Arity.TryGetValue(name, out var arity)) { _i = start; throw Fail($"unknown function '{name}'"); }
                if (args.Count < arity.Min || args.Count > arity.Max)
                {
                    _i = start;
                    throw Fail($"'{name}' takes {(arity.Min == arity.Max ? arity.Min.ToString(CultureInfo.InvariantCulture) : arity.Min + "+")} argument(s), got {args.Count}");
                }
                return new Call(name, args.ToArray());
            }

            private Node Number()
            {
                var start = _i;
                while (_i < _src.Length && (char.IsDigit(_src[_i]) || _src[_i] == '.')) _i++;
                if (_i < _src.Length && (_src[_i] == 'e' || _src[_i] == 'E'))
                {
                    var save = _i;
                    _i++;
                    if (_i < _src.Length && (_src[_i] == '+' || _src[_i] == '-')) _i++;
                    if (_i < _src.Length && char.IsDigit(_src[_i])) { while (_i < _src.Length && char.IsDigit(_src[_i])) _i++; }
                    else _i = save;
                }
                var text = _src.Substring(start, _i - start);
                if (!double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var d)) { _i = start; throw Fail($"bad number '{text}'"); }
                return new Num(d);
            }

            private void Ws()
            {
                while (_i < _src.Length && char.IsWhiteSpace(_src[_i])) _i++;
            }

            private bool PeekIs(string token)
            {
                Ws();
                return string.CompareOrdinal(_src, _i, token, 0, token.Length) == 0;
            }

            private bool Eat(string token)
            {
                if (!PeekIs(token)) return false;
                _i += token.Length;
                return true;
            }

            private ArgumentException Fail(string msg) => new ArgumentException($"Invalid expression at {_i}: {msg} in \"{_src}\"");
        }
    }

    /// <summary>Curve whose factor is a free-form <see cref="ScalingExpression"/> (JSON-serializable).</summary>
    public sealed class ExpressionCurve : ScalingCurve
    {
        internal ExpressionCurve(ScalingExpression body) { Body = body; }
        /// <summary>The parsed expression.</summary>
        public ScalingExpression Body { get; }
        public override bool Equals(object? obj) => obj is ExpressionCurve o && o.Body.Equals(Body);
        public override int GetHashCode() => Body.GetHashCode();
        public override string ToString() => $"Expression({Body.Source})";
    }

    /// <summary>
    /// Per-value formula written as text (<c>"formula": "max(scaled, base)"</c>); serializable to JSON.
    /// Inside a strategy it sees every curve variable plus <c>base</c>, <c>scaled</c> and <c>factor</c>.
    /// </summary>
    public sealed class Formula
    {
        public Formula(string source) { Expression = ScalingExpression.Parse(source, ScalingExpression.FormulaVariables); }
        public ScalingExpression Expression { get; }

        /// <summary>
        /// True when the formula is <c>base × (screen-only E)</c>: the strategy evaluates <c>E</c> once per window
        /// and needs no per-value cache. PT Verdadeiro quando a fórmula é <c>base × E</c> (E só da tela).
        /// </summary>
        public bool IsProportional => Expression.BaseCoefficient != null;

        /// <summary>The formula as a <see cref="ValueTransform"/> (curve-context variables read as NaN).</summary>
        public ValueTransform AsTransform() => Transform;

        internal float Evaluate(ResolvedScaling r, float baseValue, float scaled) =>
            (float)Expression.Evaluate(ScalingExpression.Variables(r.Screen, r.ReferenceDp > 0f ? r.AxisDp / r.ReferenceDp : 1f,
                r.AxisDp, r.ReferenceDp, r.Config.Reference, baseValue, scaled, r.Factor));

        private float Transform(float baseValue, float scaled, ScreenSnapshot screen) =>
            (float)Expression.Evaluate(ScalingExpression.Variables(screen, float.NaN, float.NaN, float.NaN,
                ReferenceScreen.Default, baseValue, scaled, baseValue != 0f ? scaled / baseValue : float.NaN));

        public override bool Equals(object? obj) => obj is Formula o && o.Expression.Equals(Expression);
        public override int GetHashCode() => Expression.GetHashCode();
        public override string ToString() => $"Formula({Expression.Source})";
    }
}

// ── CustomEngine.cs ──
namespace AppDimensGames.Custom
{
    /// <summary>
    /// Everything a strategy needs for one window: the screen-only <see cref="Factor"/> plus the
    /// value-dependent parts. Computed once per snapshot and memoized on the strategy.
    /// </summary>
    public sealed class ResolvedScaling
    {
        internal ResolvedScaling(ScreenSnapshot screen, ScalingConfig config, float factor, IReadOnlyList<string> appliedRules,
            float axisDp, float referenceDp, float curveFactor, float aspectRatioMultiplier)
        {
            Screen = screen; Config = config; Factor = factor; AppliedRules = appliedRules;
            AxisDp = axisDp; ReferenceDp = referenceDp; CurveFactor = curveFactor; AspectRatioMultiplier = aspectRatioMultiplier;
            var coefficient = config.Formula?.Expression.BaseCoefficient;
            _formulaCoefficient = coefficient == null ? double.NaN : coefficient.Evaluate(ScalingExpression.Variables(
                screen, referenceDp > 0f ? axisDp / referenceDp : 1f, axisDp, referenceDp, config.Reference));
        }

        // E of a proportional formula (base * E), evaluated once for this window; NaN when the formula (if
        // any) needs the value. base * E then costs one multiply, like a curve.
        // PT E de uma fórmula proporcional, calculado uma vez por janela; NaN caso contrário.
        private readonly double _formulaCoefficient;

        public ScreenSnapshot Screen { get; }
        /// <summary>Effective config after the matching rules.</summary>
        public ScalingConfig Config { get; }
        public float Factor { get; }
        /// <summary>Names of the rules that matched, in order (unnamed rules as <c>#index</c>).</summary>
        public IReadOnlyList<string> AppliedRules { get; }
        public float AxisDp { get; }
        public float ReferenceDp { get; }
        public float CurveFactor { get; }
        public float AspectRatioMultiplier { get; }

        /// <summary>Scales <paramref name="baseValue"/> (dp) → dp.</summary>
        public float Scale(float baseValue)
        {
            var output = baseValue * Factor;
            var min = Config.MinValue;
            var max = Config.MaxValue;
            if ((min.HasValue || max.HasValue) && output != 0f)
            {
                // Bounds apply to the magnitude so negative offsets mirror positive ones; 0 stays 0.
                var magnitude = Math.Abs(output);
                if (min.HasValue && magnitude < min.Value) magnitude = min.Value;
                if (max.HasValue && magnitude > max.Value) magnitude = max.Value;
                output = output < 0f ? -magnitude : magnitude;
            }
            if (Config.Formula != null)
                output = Config.Formula.IsProportional
                    ? (float)(baseValue * _formulaCoefficient) // bit-identical to evaluating base * E per value
                    : Config.Formula.Evaluate(this, baseValue, output);
            else if (Config.Transform != null) output = Config.Transform(baseValue, output, Screen);
            return output;
        }

        /// <summary>
        /// Text size in <b>sp units</b> for toolkits that apply the system font scale themselves,
        /// corrected so the effective scale follows <see cref="ScalingConfig.FontScale"/>.
        /// </summary>
        public float ScaleSpUnits(float baseValue)
        {
            var system = Screen.FontScale;
            var correction = system > 0f ? Config.FontScale.Effective(system) / system : 1f;
            return Scale(baseValue) * correction;
        }

        /// <summary>Text size in dp after the font-scale policy (final size).</summary>
        public float ScaleSpDp(float baseValue) => Scale(baseValue) * Config.FontScale.Effective(Screen.FontScale);

        /// <summary>Human-readable breakdown, for logs and debug overlays.</summary>
        public string Explain(string strategyId)
        {
            var sb = new StringBuilder();
            sb.Append('[').Append(strategyId).Append("] ");
            sb.Append(Screen.Device.JsonName()).Append(' ');
            sb.Append(Config.Axis.JsonName()).Append('=').Append(Fmt(AxisDp)).Append("dp");
            sb.Append(" / ref ").Append(Fmt(ReferenceDp)).Append(" = ").Append(Fmt(AxisDp / ReferenceDp));
            sb.Append(" -> ").Append(Config.Curve).Append(" = ").Append(Fmt(CurveFactor));
            if (Config.Multiplier != 1f) sb.Append(" x ").Append(Fmt(Config.Multiplier));
            if (Config.AspectRatio) sb.Append(" x AR ").Append(Fmt(AspectRatioMultiplier));
            if (Config.MinFactor.HasValue || Config.MaxFactor.HasValue)
                sb.Append(" clamp[").Append(Config.MinFactor.HasValue ? Fmt(Config.MinFactor.Value) : "-").Append(", ")
                  .Append(Config.MaxFactor.HasValue ? Fmt(Config.MaxFactor.Value) : "-").Append(']');
            sb.Append(" => factor ").Append(Fmt(Factor));
            if (Config.Formula != null) sb.Append(" then ").Append(Config.Formula);
            else if (Config.Transform != null) sb.Append(" then transform");
            if (AppliedRules.Count > 0) sb.Append(" rules=[").Append(string.Join(", ", AppliedRules)).Append(']');
            return sb.ToString();
        }

        private static string Fmt(float v) => v.ToString("0.####", CultureInfo.InvariantCulture);
    }

    /// <summary>
    /// A named, user-defined scaling strategy. Create with <see cref="Define"/>, <see cref="Extend"/>,
    /// <see cref="ScalingStrategies.LoadJson"/> or a preset in <see cref="CustomPresets"/>.
    /// Immutable and thread-safe; the factor for a window is computed once and memoized, so resolving
    /// a value is one multiply (plus optional value clamps).
    /// </summary>
    public sealed class ScalingStrategy
    {
        private sealed class Memo
        {
            public Memo(object token, ResolvedScaling resolved) { Token = token; Resolved = resolved; }
            public readonly object Token;
            public readonly ResolvedScaling Resolved;
        }

        private volatile Memo? _memo;

        public ScalingStrategy(string id, ScalingConfig config)
        {
            if (string.IsNullOrWhiteSpace(id)) throw new ArgumentException("strategy id must not be blank");
            Id = id;
            Config = (config ?? throw new ArgumentNullException(nameof(config))).Validate();
            CacheId = ScalingStrategies.NextCacheId();
            IsValueDependent = Config.IsValueDependent;
        }

        public string Id { get; }
        public ScalingConfig Config { get; }

        /// <summary>
        /// Process-unique id packed into cache keys (16 bits); <c>-1</c> when the registry ran out of
        /// ids — such a strategy still works but never writes the shared cache.
        /// </summary>
        public int CacheId { get; }

        /// <summary>True when results depend on the value, not only on the screen.</summary>
        public bool IsValueDependent { get; }

        /// <summary>Creates <b>and registers</b> a strategy with the builder.</summary>
        /// <example><code>
        /// var brand = ScalingStrategy.Define("brand", s => {
        ///     s.SetReference(360, 640);
        ///     s.Curve = ScalingCurve.Power(0.8f);
        ///     s.Clamp(0.85f, 1.6f);
        ///     s.On(new[] { DeviceClass.Tablet }, r => r.Curve = ScalingCurve.Logarithmic(0.4f));
        /// });
        /// </code></example>
        public static ScalingStrategy Define(string id, Action<ScalingStrategyBuilder> configure, bool register = true)
        {
            var builder = new ScalingStrategyBuilder();
            configure(builder);
            var s = new ScalingStrategy(id, builder.Build());
            return register ? ScalingStrategies.Register(s) : s;
        }

        /// <summary>
        /// One-liner strategy from a <b>text</b> formula, for JSON, remote config or when the formula comes from
        /// outside the code — the formula <b>is</b> the final value. Same names as the code form:
        /// <code>
        /// var hud = ScalingStrategy.Formula("base * pow(sw / 360, 0.8)");
        /// 16.Cdp(hud);    // or straight: 16.Cdp("base * pow(sw / 360, 0.8)")
        /// </code>
        /// Variables: <c>base</c> (the value you pass, e.g. 16), <c>sw</c>, <c>width</c>, <c>height</c>, <c>shortSide</c>,
        /// <c>longSide</c>, <c>diagonal</c>, <c>aspectRatio</c>, <c>density</c>, <c>fontScale</c>, the device flags
        /// (<c>tablet</c>, <c>tv</c>, <c>landscape</c>, …) and <c>ratio</c> (<c>sw / 300</c>, the ratio <c>MathKernels.Scaled</c> uses).
        /// Same language and same numbers on every AppDimens platform (see <see cref="ScalingExpression"/>).
        /// <para>Writing it as <c>base * (…)</c> keeps it on the one-multiply fast path (the <c>(…)</c> part is computed
        /// once per window). Any other shape still works and is cached per value and window.</para>
        /// <para>Without an <paramref name="id"/> the strategy is shared per formula text (calling this again with the
        /// same text returns the same instance) and is not registered. With an id, a new strategy is created and
        /// registered unless <paramref name="register"/> is <c>false</c>. Parse errors throw right away.</para>
        /// <para>PT Estratégia em uma linha a partir de uma fórmula em texto — a fórmula <b>é</b> o valor final.
        /// Escrever como <c>base * (…)</c> mantém o caminho rápido (uma multiplicação).</para>
        /// </summary>
        public static ScalingStrategy Formula(string formula, string? id = null, bool? register = null)
        {
            var doRegister = register ?? id != null;
            if (id == null && !doRegister) return FormulaStrategies.Get(formula);
            var s = new ScalingStrategy(id ?? FormulaStrategies.IdOf(formula), new ScalingConfig(formula: new Formula(formula)));
            return doRegister ? ScalingStrategies.Register(s) : s;
        }

        /// <summary>
        /// One-liner strategy from a <b>code</b> formula — the result <b>is</b> the final value. Typed C# with
        /// IntelliSense, no strings, no limits:
        /// <code>
        /// var hud  = ScalingStrategy.Formula(s => s.Base * s.Pow(s.Sw / 360f, 0.8f));
        /// var card = ScalingStrategy.Formula(s => s.Tablet ? s.Base * 1.2f : s.Base * s.Ratio);
        /// 16.Cdp(hud);
        /// </code>
        /// The scope (<see cref="FormulaScope"/>) has <c>Base</c> (the value you pass), the window
        /// (<see cref="ScreenScope"/>: <c>Sw</c>, <c>Width</c>, <c>Height</c>, <c>Ratio</c>, <c>Tablet</c>,
        /// <c>Landscape</c>, …) and <c>Pow</c>, <c>Clamp</c>, <c>Min</c>, <c>Max</c>, <c>Lerp</c>… — the same names as
        /// the text language. Must be pure (results are cached per value and window); declare it once (e.g. a
        /// <c>static readonly</c> field). Not JSON-serializable: the text form
        /// <see cref="Formula(string, string?, bool?)"/> is. Without an <paramref name="id"/> a unique
        /// <c>formula#N</c> id is generated and it is not registered; an id registers.
        /// <para>PT Estratégia em uma linha a partir de uma fórmula em <b>código</b> — o resultado <b>é</b> o valor
        /// final. C# tipado com autocomplete, sem strings, sem limites.</para>
        /// </summary>
        public static ScalingStrategy Formula(Func<FormulaScope, float> formula, string? id = null, bool? register = null)
        {
            if (formula == null) throw new ArgumentNullException(nameof(formula));
            var s = new ScalingStrategy(id ?? FormulaStrategies.NextLambdaId(),
                new ScalingConfig(transform: (baseValue, _, screen) => formula(new FormulaScope(screen, baseValue))));
            return register ?? id != null ? ScalingStrategies.Register(s) : s;
        }

        /// <summary>Resolves (memoized) for <paramref name="screen"/>.</summary>
        public ResolvedScaling Resolve(ScreenSnapshot screen) => Resolve(screen, () => screen);

        /// <summary>
        /// Resolves for a platform snapshot <paramref name="token"/> (e.g. <c>Metrics</c>), building
        /// the <see cref="ScreenSnapshot"/> only on a memo miss. The token must have value equality.
        /// </summary>
        public ResolvedScaling Resolve(object token, Func<ScreenSnapshot> snapshot)
        {
            var m = _memo;
            if (m != null && (ReferenceEquals(m.Token, token) || m.Token.Equals(token))) return m.Resolved;
            var resolved = ScalingEngine.Resolve(Config, snapshot());
            _memo = new Memo(token, resolved);
            return resolved;
        }

        public float Factor(ScreenSnapshot screen) => Resolve(screen).Factor;
        public float Scale(float baseValue, ScreenSnapshot screen) => Resolve(screen).Scale(baseValue);
        public string Explain(ScreenSnapshot screen) => Resolve(screen).Explain(Id);

        /// <summary>New strategy that starts from this one; rules of both are kept (parent first).</summary>
        public ScalingStrategy Extend(string id, Action<ScalingStrategyBuilder> configure, bool register = true)
        {
            var builder = new ScalingStrategyBuilder(Config);
            configure(builder);
            var s = new ScalingStrategy(id, builder.Build());
            return register ? ScalingStrategies.Register(s) : s;
        }

        /// <summary>Same strategy on another axis (e.g. heights). Id: <c>"&lt;id&gt;@&lt;axis&gt;"</c>.</summary>
        public ScalingStrategy WithAxis(ScalingAxis axis)
        {
            if (axis == Config.Axis) return this;
            var derivedId = Id + "@" + axis.JsonName();
            return ScalingStrategies.Derived(derivedId, () => new ScalingStrategy(derivedId, Config.With(axis: axis)));
        }

        /// <summary>JSON for this strategy (throws for lambda curves/transforms).</summary>
        public string ToJson() => ScalingStrategyJson.Encode(this);

        public override string ToString() => $"ScalingStrategy({Id})";
    }

    /// <summary>Pure math shared by every platform binding.</summary>
    internal static class ScalingEngine
    {
        /// <summary>Default AR sensitivity — same constant as the built-in strategies (0.08 / 30).</summary>
        public const float SensitivityDefault = 0.08f / 30f;
        public const float ReferenceAspectRatio = 1.78f;

        public static ResolvedScaling Resolve(ScalingConfig baseConfig, ScreenSnapshot screen)
        {
            var cfg = baseConfig;
            var applied = new List<string>(0);
            for (var i = 0; i < baseConfig.Rules.Count; i++)
            {
                var rule = baseConfig.Rules[i];
                if (!rule.Condition.Matches(screen)) continue;
                cfg = cfg.Apply(rule.Patch);
                applied.Add(rule.Name ?? "#" + i.ToString(CultureInfo.InvariantCulture));
            }
            var axisDp = screen.Read(cfg.Axis);
            var refDp = cfg.Reference.Read(cfg.Axis);
            if (cfg.IgnoreMultiWindow && screen.IsMultiWindow)
                return new ResolvedScaling(screen, cfg, 1f, applied, axisDp, refDp, 1f, 1f);
            var ratio = refDp > 0f ? axisDp / refDp : 1f;
            var curveFactor = Curve(cfg.Curve, ratio, axisDp, refDp, cfg.Reference, screen);
            var factor = curveFactor * cfg.Multiplier;
            var arMul = 1f;
            if (cfg.AspectRatio)
            {
                var k = cfg.Sensitivity ?? SensitivityDefault;
                arMul = 1f + k * (float)Math.Log(screen.AspectRatio / ReferenceAspectRatio);
                factor *= arMul;
            }
            if (cfg.MinFactor.HasValue && factor < cfg.MinFactor.Value) factor = cfg.MinFactor.Value;
            if (cfg.MaxFactor.HasValue && factor > cfg.MaxFactor.Value) factor = cfg.MaxFactor.Value;
            if (!float.IsFinite(factor)) throw new InvalidOperationException($"custom strategy produced a non-finite factor ({factor})");
            return new ResolvedScaling(screen, cfg, factor, applied, axisDp, refDp, curveFactor, arMul);
        }

        public static float Curve(ScalingCurve curve, float ratio, float axisDp, float refDp, ReferenceScreen reference, ScreenSnapshot screen)
        {
            switch (curve)
            {
                case PowerCurve p: return ratio > 0f ? (float)Math.Pow(ratio, p.Exponent) : 0f;
                case LogarithmicCurve l: return ratio > 0f ? 1f + l.K * (float)Math.Log(ratio) : 1f;
                case InterpolatedCurve t: return 1f + (ratio - 1f) * t.T;
                case ConstantCurve c: return c.Factor;
                case BreakpointsCurve b: return Interpolate(b.Points, axisDp);
                case CustomCurve f: return f.Function(ratio, screen);
                case ExpressionCurve x:
                    return (float)x.Body.Evaluate(ScalingExpression.Variables(screen, ratio, axisDp, refDp, reference));
                default: return ratio; // Linear
            }
        }

        private static float Interpolate(IReadOnlyList<Breakpoint> points, float x)
        {
            var first = points[0];
            if (x <= first.At) return first.Factor;
            for (var i = 1; i < points.Count; i++)
            {
                var b = points[i];
                if (x <= b.At)
                {
                    var a = points[i - 1];
                    var span = b.At - a.At;
                    return span <= 0f ? b.Factor : a.Factor + (b.Factor - a.Factor) * ((x - a.At) / span);
                }
            }
            return points[points.Count - 1].Factor;
        }
    }

    /// <summary>Process-wide registry of strategies by id, plus the default used by <c>16.Cdp()</c>.</summary>
    public static class ScalingStrategies
    {
        /// <summary>Largest id that fits the 16-bit custom cache key field.</summary>
        public const int MaxCacheId = 0xFFFF;

        private static readonly ConcurrentDictionary<string, ScalingStrategy> ById = new ConcurrentDictionary<string, ScalingStrategy>();
        private static readonly ConcurrentDictionary<string, ScalingStrategy> DerivedCache = new ConcurrentDictionary<string, ScalingStrategy>();
        private static int _cacheIds = -1;
        private static volatile ScalingStrategy? _default;

        internal static int NextCacheId()
        {
            var next = Interlocked.Increment(ref _cacheIds);
            return next >= 0 && next <= MaxCacheId ? next : -1;
        }

        /// <summary>
        /// Strategy used when none is passed and none is provided by scope.
        /// Defaults to <see cref="BuiltInStrategies.Scaled"/> (same numbers as <c>MathKernels.Scaled</c>).
        /// </summary>
        public static ScalingStrategy Default
        {
            get => _default ?? BuiltInStrategies.Scaled;
            set => _default = value;
        }

        /// <summary>Registers (or replaces) <paramref name="strategy"/> under its id.</summary>
        public static ScalingStrategy Register(ScalingStrategy strategy)
        {
            ById[strategy.Id] = strategy;
            return strategy;
        }

        /// <summary>Strategy for <paramref name="id"/> (registered, built-in or preset), or <c>null</c>.</summary>
        public static ScalingStrategy? Get(string id) =>
            ById.TryGetValue(id, out var s) ? s : BuiltInStrategies.ByName(id) ?? CustomPresets.ByName(id);

        /// <summary>Like <see cref="Get"/> but throws a descriptive error.</summary>
        public static ScalingStrategy Require(string id) =>
            Get(id) ?? throw new KeyNotFoundException(
                $"No scaling strategy '{id}'. Registered: [{string.Join(", ", ById.Keys.OrderBy(k => k, StringComparer.Ordinal))}]");

        /// <summary>Ids registered by the app (built-ins/presets excluded).</summary>
        public static IReadOnlyCollection<string> Ids => ById.Keys.ToArray();

        public static void Unregister(string id) => ById.TryRemove(id, out _);

        /// <summary>
        /// Parses a strategies document (see <c>custom-strategy.schema.json</c>), registers every
        /// strategy and applies its <c>default</c>. Returns the parsed strategies by id.
        /// </summary>
        public static IReadOnlyDictionary<string, ScalingStrategy> LoadJson(string json)
        {
            var doc = ScalingStrategyJson.Decode(json);
            foreach (var s in doc.Strategies.Values) Register(s);
            if (doc.DefaultId != null)
                Default = doc.Strategies.TryGetValue(doc.DefaultId, out var d) ? d : Require(doc.DefaultId);
            return doc.Strategies;
        }

        /// <summary>Encodes the registered strategies (plus the default id) as a document.</summary>
        public static string ExportJson() =>
            ScalingStrategyJson.EncodeDocument(ById.Values.OrderBy(s => s.Id, StringComparer.Ordinal).ToArray(), _default?.Id);

        /// <summary>
        /// Strategy whose value is the text <paramref name="formula"/> (<c>"base * pow(sw / 360, 0.8)"</c>), shared
        /// per text and not registered. Same as <see cref="ScalingStrategy.Formula(string, string?, bool?)"/> without an id.
        /// <para>PT Estratégia cujo valor é a fórmula em texto, compartilhada por texto.</para>
        /// </summary>
        public static ScalingStrategy Formula(string formula) => FormulaStrategies.Get(formula);

        internal static ScalingStrategy Derived(string id, Func<ScalingStrategy> create) =>
            DerivedCache.GetOrAdd(id, _ => create());

        /// <summary>Test helper: clears registrations, shared formula strategies and the default.</summary>
        public static void ResetForTesting()
        {
            ById.Clear();
            DerivedCache.Clear();
            FormulaStrategies.Clear();
            _default = null;
        }
    }

    /// <summary>
    /// What a code formula can read, with the <b>same names as the text formulas</b> (PascalCase), so
    /// IntelliSense completes them and typos fail at compile time. Values are in dp; flags are <c>bool</c>.
    /// <para>PT O que uma fórmula em código pode ler, com os <b>mesmos nomes das fórmulas em texto</b>: o IDE
    /// autocompleta e erros de digitação falham na compilação.</para>
    /// </summary>
    public class ScreenScope
    {
        internal ScreenScope(ScreenSnapshot screen) { Screen = screen; }

        /// <summary>The full window snapshot. PT O snapshot completo da janela.</summary>
        public ScreenSnapshot Screen { get; }

        /// <summary>Smallest width (dp).</summary>
        public float Sw => Screen.SmallestWidthDp;
        public float Width => Screen.WidthDp;
        public float Height => Screen.HeightDp;
        public float ShortSide => Screen.MinDp;
        public float LongSide => Screen.MaxDp;
        public float Diagonal => Screen.Read(ScalingAxis.Diagonal);
        public float Perimeter => Screen.Read(ScalingAxis.Perimeter);
        public float AspectRatio => Screen.AspectRatio;
        public float Density => Screen.Density;
        public float FontScale => Screen.FontScale;

        /// <summary><c>Sw / 300</c> — the ratio <c>MathKernels.Scaled</c> uses (<c>Base * Ratio</c> = <c>MathKernels.Scaled</c>).</summary>
        public float Ratio => Sw / ReferenceScreen.Default.Read(ScalingAxis.SmallestWidth);

        public bool Landscape => Screen.IsLandscape;
        public bool Portrait => !Screen.IsLandscape;
        public bool MultiWindow => Screen.IsMultiWindow;
        public DeviceClass Device => Screen.Device;
        public bool Phone => Screen.Device == DeviceClass.Phone;
        public bool Tablet => Screen.Device == DeviceClass.Tablet;
        public bool Desktop => Screen.Device == DeviceClass.Desktop;
        public bool Tv => Screen.Device == DeviceClass.Tv;
        public bool Watch => Screen.Device == DeviceClass.Watch;
        public bool Car => Screen.Device == DeviceClass.Car;
        public bool Vr => Screen.Device == DeviceClass.Vr;

        // Math helpers on float, so no cast or using is needed. PT Funções matemáticas em float, sem cast.
        public float Pow(float x, float exponent) => (float)Math.Pow(x, exponent);
        public float Sqrt(float x) => (float)Math.Sqrt(x);
        public float Ln(float x) => (float)Math.Log(x);
        public float Log10(float x) => (float)Math.Log10(x);
        public float Exp(float x) => (float)Math.Exp(x);
        public float Abs(float x) => Math.Abs(x);
        /// <summary>Half up, like the text <c>round</c>: <c>floor(x + 0.5)</c>.</summary>
        public float Round(float x) => (float)Math.Floor(x + 0.5f);
        public float Min(float a, float b) => Math.Min(a, b);
        public float Max(float a, float b) => Math.Max(a, b);
        public float Clamp(float x, float min, float max) => Math.Max(min, Math.Min(max, x));
        public float Lerp(float a, float b, float t) => a + (b - a) * t;
        public float Smoothstep(float edge0, float edge1, float x)
        {
            var t = Clamp((x - edge0) / (edge1 - edge0), 0f, 1f);
            return t * t * (3f - 2f * t);
        }
    }

    /// <summary>
    /// <see cref="ScreenScope"/> plus <see cref="Base"/>, the value being scaled (the <c>16</c> in <c>16.Cdp(hud)</c>).
    /// <para>PT <see cref="ScreenScope"/> mais <see cref="Base"/>, o valor sendo escalado.</para>
    /// </summary>
    public sealed class FormulaScope : ScreenScope
    {
        internal FormulaScope(ScreenSnapshot screen, float baseValue) : base(screen) { Base = baseValue; }

        /// <summary>The value being scaled (dp).</summary>
        public float Base { get; }
    }

    /// <summary>
    /// Strategy from a programmable <b>factor</b> — you return the number that multiplies every value:
    /// <code>
    /// var product = CustomScaleStrategy.Create(s => s.Clamp(s.Width / 360f, 0.85f, 1.80f));
    /// var living  = CustomScaleStrategy.Create(s => s.Tv ? s.Height / 540f : s.Ratio);
    /// 16.Cdp(product);   // 16 × factor
    /// </code>
    /// The scope is the window (<see cref="ScreenScope"/>) with IntelliSense, plus any C# code of yours. The factor
    /// depends only on the window, so it runs once per window and every value then costs one multiply (no
    /// per-value cache). A non-finite factor throws when the window resolves. Without an id a unique
    /// <c>scale#N</c> id is generated and it is not registered; an id registers. Not JSON-serializable: for JSON,
    /// use a text curve (<c>ScalingCurve.Expression("clamp(width / 360, 0.85, 1.8)")</c>).
    /// <para>PT Estratégia a partir de um <b>fator</b> programável. Roda uma vez por janela; cada valor custa uma
    /// multiplicação.</para>
    /// </summary>
    public static class CustomScaleStrategy
    {
        private static int _ids;

        public static ScalingStrategy Create(Func<ScreenScope, float> factor, string? id = null, bool? register = null)
        {
            if (factor == null) throw new ArgumentNullException(nameof(factor));
            var curve = ScalingCurve.Custom((_, screen) => factor(new ScreenScope(screen)));
            var s = new ScalingStrategy(id ?? "scale#" + Interlocked.Increment(ref _ids).ToString(CultureInfo.InvariantCulture),
                new ScalingConfig(curve: curve));
            return register ?? id != null ? ScalingStrategies.Register(s) : s;
        }
    }

    /// <summary>Shared strategies for inline formulas (<c>16.Cdp("…")</c>), keyed by the formula text.</summary>
    internal static class FormulaStrategies
    {
        /// <summary>Bound for distinct texts; past it, strategies are built per call (still correct).</summary>
        public const int Max = 256;

        private static readonly ConcurrentDictionary<string, ScalingStrategy> ByText = new ConcurrentDictionary<string, ScalingStrategy>(StringComparer.Ordinal);
        private static readonly object Gate = new object();
        private static int _lambdaIds;

        public static ScalingStrategy Get(string formula)
        {
            if (formula == null) throw new ArgumentNullException(nameof(formula));
            if (ByText.TryGetValue(formula, out var cached)) return cached;
            var s = new ScalingStrategy(IdOf(formula), new ScalingConfig(formula: new Formula(formula)));
            lock (Gate) // misses only: keeps the bound exact under contention
            {
                if (ByText.TryGetValue(formula, out cached)) return cached;
                if (ByText.Count >= Max) return s;
                ByText[formula] = s;
                return s;
            }
        }

        public static string IdOf(string formula) => "formula:" + formula;

        public static string NextLambdaId() =>
            "formula#" + Interlocked.Increment(ref _lambdaIds).ToString(CultureInfo.InvariantCulture);

        public static void Clear() => ByText.Clear();
    }

    /// <summary>
    /// The built-in strategies expressed as custom configs — starting points for
    /// <see cref="ScalingStrategy.Extend"/> and for JSON <c>"extends": "power"</c>. Their factors match
    /// the built-in modules (default smallest-width path, no aspect ratio).
    /// </summary>
    public static class BuiltInStrategies
    {
        /// <summary><c>sw / 300</c> — same as <c>MathKernels.Scaled</c>.</summary>
        public static readonly ScalingStrategy Scaled = new ScalingStrategy("scaled", ScalingConfig.Default);
        /// <summary><c>(sw / 300)^0.75</c> — same as the power module.</summary>
        public static readonly ScalingStrategy Power = new ScalingStrategy("power", new ScalingConfig(curve: ScalingCurve.Power(0.75f)));
        /// <summary><c>1 + 0.4·ln(sw / 300)</c> — same as the logarithmic module.</summary>
        public static readonly ScalingStrategy Logarithmic = new ScalingStrategy("logarithmic", new ScalingConfig(curve: ScalingCurve.Logarithmic(0.4f)));
        /// <summary><c>1 + (sw / 300 − 1)·0.5</c> — same as the interpolated module.</summary>
        public static readonly ScalingStrategy Interpolated = new ScalingStrategy("interpolated", new ScalingConfig(curve: ScalingCurve.Interpolated(0.5f)));
        /// <summary><c>√(w² + h²) / 611.63</c> — same as the diagonal module.</summary>
        public static readonly ScalingStrategy Diagonal = new ScalingStrategy("diagonal", new ScalingConfig(axis: ScalingAxis.Diagonal));
        /// <summary><c>(w + h) / 833</c> — same as the perimeter module.</summary>
        public static readonly ScalingStrategy Perimeter = new ScalingStrategy("perimeter", new ScalingConfig(axis: ScalingAxis.Perimeter));
        /// <summary>Plain dp (factor 1).</summary>
        public static readonly ScalingStrategy Fixed = new ScalingStrategy("fixed", new ScalingConfig(curve: ScalingCurve.Constant(1f)));

        public static IReadOnlyList<ScalingStrategy> All => new[] { Scaled, Power, Logarithmic, Interpolated, Diagonal, Perimeter, Fixed };

        public static ScalingStrategy? ByName(string name) =>
            All.FirstOrDefault(s => string.Equals(s.Id, name, StringComparison.OrdinalIgnoreCase));
    }

    /// <summary>Ready-made strategies for common product needs. Use as-is, or <c>Extend</c> them.</summary>
    public static class CustomPresets
    {
        /// <summary>Linear on phones; damped (power 0.5) on tablets/desktop. Factor capped at 1.8.</summary>
        public static readonly ScalingStrategy TabletFriendly = ScalingStrategy.Define("tabletFriendly", s =>
        {
            s.Clamp(max: 1.8f);
            s.On(new[] { DeviceClass.Tablet, DeviceClass.Desktop }, r => r.Curve = ScalingCurve.Power(0.5f), "large");
        }, register: false);

        /// <summary>Designed on a compact phone: grows at half speed and stays within 0.9–1.4×.</summary>
        public static readonly ScalingStrategy CompactFirst = ScalingStrategy.Define("compactFirst", s =>
        {
            s.SetReference(360f, 640f);
            s.Curve = ScalingCurve.Interpolated(0.5f);
            s.Clamp(0.9f, 1.4f);
        }, register: false);

        /// <summary>10-foot UI: on TV, scale by window height against a 540 dp frame, 1×–2×.</summary>
        public static readonly ScalingStrategy TvSafe = ScalingStrategy.Define("tvSafe", s =>
            s.On(new[] { DeviceClass.Tv }, r =>
            {
                r.Axis = ScalingAxis.Height;
                r.SetReference(960f, 540f);
                r.Clamp(1f, 2f);
            }, "tv"), register: false);

        /// <summary>Wearables: scale against a 192 dp face and keep within ±15 %.</summary>
        public static readonly ScalingStrategy Wearable = ScalingStrategy.Define("wearable", s =>
            s.On(new[] { DeviceClass.Watch }, r =>
            {
                r.Axis = ScalingAxis.Min;
                r.SetReference(192f, 192f);
                r.Clamp(0.85f, 1.15f);
            }, "watch"), register: false);

        /// <summary>Game HUD: shorter side, sublinear growth, aspect-ratio aware, fixed-size text.</summary>
        public static readonly ScalingStrategy GameHud = ScalingStrategy.Define("gameHud", s =>
        {
            s.Axis = ScalingAxis.Min;
            s.Curve = ScalingCurve.Power(0.85f);
            s.EnableAspectRatio();
            s.Clamp(0.75f, 2.5f);
            s.IgnoreFontScale();
        }, register: false);

        /// <summary>Accessible text: follows the user font scale up to 1.3× and damps screen growth.</summary>
        public static readonly ScalingStrategy ReadableText = ScalingStrategy.Define("readableText", s =>
        {
            s.Curve = ScalingCurve.Logarithmic(0.4f);
            s.ClampFontScale(1.3f);
        }, register: false);

        public static IReadOnlyList<ScalingStrategy> All => new[] { TabletFriendly, CompactFirst, TvSafe, Wearable, GameHud, ReadableText };

        public static ScalingStrategy? ByName(string name) =>
            All.FirstOrDefault(s => string.Equals(s.Id, name, StringComparison.OrdinalIgnoreCase));
    }
}

// ── CustomBuilder.cs ──
namespace AppDimensGames.Custom
{
    /// <summary>Fields shared by the strategy root (<see cref="ScalingStrategyBuilder"/>) and rule blocks (<see cref="ScalingPatchBuilder"/>).</summary>
    public abstract class ScalingFields
    {
        private protected ScalingFields() { }

        public abstract ScalingAxis? Axis { get; set; }
        public abstract ScalingCurve? Curve { get; set; }
        public abstract float? Multiplier { get; set; }
        public abstract FontScalePolicy? FontScale { get; set; }
        public abstract bool? IgnoreMultiWindow { get; set; }

        private protected abstract void ApplyReference(ReferenceScreen reference);
        private protected abstract void ApplyFactorBounds(float? min, float? max);
        private protected abstract void ApplyValueBounds(float? min, float? max);
        private protected abstract void ApplyAspectRatio(bool enabled, float? sensitivity);
        private protected abstract void ApplyTransform(ValueTransform transform);
        private protected abstract void ApplyFormula(Formula formula);

        /// <summary>Design frame in dp (default 300×533).</summary>
        public void SetReference(float width = 300f, float height = 533f) => ApplyReference(new ReferenceScreen(width, height));

        /// <summary>Bounds for the <b>factor</b> (<c>Clamp(max: 1.5f)</c>).</summary>
        public void Clamp(float? min = null, float? max = null) => ApplyFactorBounds(min, max);

        /// <summary>Bounds for the <b>resulting dp</b> (value-dependent → cached).</summary>
        public void ClampValue(float? min = null, float? max = null) => ApplyValueBounds(min, max);

        /// <summary>Aspect-ratio correction <c>× (1 + k·ln(AR / 1.78))</c>.</summary>
        public void EnableAspectRatio(bool enabled = true, float? sensitivity = null) => ApplyAspectRatio(enabled, sensitivity);

        /// <summary>Per-value pure hook (value-dependent → cached).</summary>
        public void Transform(ValueTransform transform) => ApplyTransform(transform);

        /// <summary>
        /// Per-value formula as text (value-dependent → cached), e.g. <c>SetFormula("max(scaled, base)")</c> or a
        /// full replacement <c>SetFormula("base * pow(sw / 360, 0.7) + 2")</c>. See <see cref="ScalingExpression"/>.
        /// </summary>
        public void SetFormula(string source) => ApplyFormula(new Formula(source));

        /// <summary>Shortcut: multiply the factor.</summary>
        public void Multiply(float factor) => Multiplier = factor;

        public void FollowFontScale() => FontScale = FontScalePolicy.Follow;
        public void IgnoreFontScale() => FontScale = FontScalePolicy.Ignore;
        public void ClampFontScale(float max) => FontScale = FontScalePolicy.Clamp(max);
    }

    /// <summary>Block of a rule: every field is optional and overrides the strategy only when the rule matches.</summary>
    public sealed class ScalingPatchBuilder : ScalingFields
    {
        private ReferenceScreen? _reference;
        private float? _minFactor, _maxFactor, _minValue, _maxValue, _sensitivity;
        private bool? _aspect;
        private ValueTransform? _transform;
        private Formula? _formula;

        internal ScalingPatchBuilder() { }

        public override ScalingAxis? Axis { get; set; }
        public override ScalingCurve? Curve { get; set; }
        public override float? Multiplier { get; set; }
        public override FontScalePolicy? FontScale { get; set; }
        public override bool? IgnoreMultiWindow { get; set; }

        private protected override void ApplyReference(ReferenceScreen reference) => _reference = reference;
        private protected override void ApplyFactorBounds(float? min, float? max) { _minFactor = min; _maxFactor = max; }
        private protected override void ApplyValueBounds(float? min, float? max) { _minValue = min; _maxValue = max; }
        private protected override void ApplyAspectRatio(bool enabled, float? sensitivity) { _aspect = enabled; _sensitivity = sensitivity; }
        private protected override void ApplyTransform(ValueTransform transform) { _transform = transform; _formula = null; }
        private protected override void ApplyFormula(Formula formula) { _formula = formula; _transform = null; }

        internal ScalingPatch Build() => new ScalingPatch(
            _reference, Axis, Curve, Multiplier, _minFactor, _maxFactor, _minValue, _maxValue,
            _aspect, _sensitivity, FontScale, IgnoreMultiWindow, _transform, _formula);
    }

    /// <summary>Root builder used by <see cref="ScalingStrategy.Define"/> and <see cref="ScalingStrategy.Extend"/>.</summary>
    public sealed class ScalingStrategyBuilder : ScalingFields
    {
        private ScalingConfig _config;
        private readonly List<ScalingRule> _rules;

        public ScalingStrategyBuilder(ScalingConfig? baseConfig = null)
        {
            _config = baseConfig ?? ScalingConfig.Default;
            _rules = _config.Rules.ToList();
        }

        public override ScalingAxis? Axis
        {
            get => _config.Axis;
            set => _config = _config.With(axis: value ?? throw new ArgumentNullException(nameof(Axis)));
        }

        public override ScalingCurve? Curve
        {
            get => _config.Curve;
            set => _config = _config.With(curve: value ?? throw new ArgumentNullException(nameof(Curve)));
        }

        public override float? Multiplier
        {
            get => _config.Multiplier;
            set => _config = _config.With(multiplier: value ?? 1f);
        }

        public override FontScalePolicy? FontScale
        {
            get => _config.FontScale;
            set => _config = _config.With(fontScale: value ?? FontScalePolicy.Follow);
        }

        public override bool? IgnoreMultiWindow
        {
            get => _config.IgnoreMultiWindow;
            set => _config = _config.With(ignoreMultiWindow: value ?? false);
        }

        private protected override void ApplyReference(ReferenceScreen reference) => _config = _config.With(reference: reference);
        private protected override void ApplyFactorBounds(float? min, float? max) => _config = _config.WithFactorBounds(min, max);
        private protected override void ApplyValueBounds(float? min, float? max) => _config = _config.WithValueBounds(min, max);
        private protected override void ApplyAspectRatio(bool enabled, float? sensitivity) => _config = _config.WithAspectRatio(enabled, sensitivity);
        private protected override void ApplyTransform(ValueTransform transform) => _config = _config.WithTransform(transform);
        private protected override void ApplyFormula(Formula formula) => _config = _config.WithFormula(formula);

        /// <summary>Rule for one or more device classes.</summary>
        public void On(IEnumerable<DeviceClass> devices, Action<ScalingPatchBuilder> configure, string? name = null) =>
            Rule(new ScreenCondition(devices: devices), name, configure);

        /// <summary>Rule for a single device class.</summary>
        public void On(DeviceClass device, Action<ScalingPatchBuilder> configure, string? name = null) =>
            Rule(new ScreenCondition(devices: new[] { device }), name, configure);

        /// <summary>Rule for an arbitrary <paramref name="condition"/>.</summary>
        public void On(ScreenCondition condition, Action<ScalingPatchBuilder> configure, string? name = null) =>
            Rule(condition, name, configure);

        /// <summary>Rule by screen ranges (<c>min &lt;= v &lt; max</c>, dp).</summary>
        public void OnScreen(Action<ScalingPatchBuilder> configure,
            float? minSmallestWidth = null, float? maxSmallestWidth = null,
            float? minWidth = null, float? maxWidth = null,
            float? minHeight = null, float? maxHeight = null,
            float? minAspectRatio = null, float? maxAspectRatio = null,
            bool? landscape = null, IEnumerable<DeviceClass>? devices = null, bool? multiWindow = null,
            string? name = null) =>
            Rule(new ScreenCondition(devices, landscape, minSmallestWidth, maxSmallestWidth, minWidth, maxWidth,
                minHeight, maxHeight, minAspectRatio, maxAspectRatio, multiWindow), name, configure);

        public void Landscape(Action<ScalingPatchBuilder> configure) => Rule(new ScreenCondition(landscape: true), "landscape", configure);
        public void Portrait(Action<ScalingPatchBuilder> configure) => Rule(new ScreenCondition(landscape: false), "portrait", configure);
        public void MultiWindow(Action<ScalingPatchBuilder> configure) => Rule(new ScreenCondition(multiWindow: true), "multiWindow", configure);

        /// <summary>Shortcut for <c>sw &gt;= 600</c> (tablet-like windows, any UI mode).</summary>
        public void LargeScreens(Action<ScalingPatchBuilder> configure) =>
            Rule(new ScreenCondition(minSmallestWidth: CustomNames.TabletMinSmallestWidthDp), "largeScreens", configure);

        private void Rule(ScreenCondition condition, string? name, Action<ScalingPatchBuilder> configure)
        {
            var b = new ScalingPatchBuilder();
            configure(b);
            _rules.Add(new ScalingRule(condition, b.Build(), name));
        }

        internal ScalingConfig Build() => _config.WithRules(_rules);
    }
}

// ── CustomJson.cs ──
namespace AppDimensGames.Custom
{
    /// <summary>Parsed strategies document.</summary>
    public sealed class ScalingStrategyDocument
    {
        internal ScalingStrategyDocument(IReadOnlyDictionary<string, ScalingStrategy> strategies, string? defaultId)
        {
            Strategies = strategies;
            DefaultId = defaultId;
        }

        public IReadOnlyDictionary<string, ScalingStrategy> Strategies { get; }
        public string? DefaultId { get; }
    }

    /// <summary>
    /// JSON codec for the cross-platform strategy format
    /// (<c>appdimens-skills/schemas/custom-strategy.schema.json</c>). Self-contained (no
    /// System.Text.Json) so the same code runs in .NET, Unity and Godot.
    /// <code>
    /// { "version": 1, "default": "brand",
    ///   "strategies": [ { "id": "brand", "extends": "power",
    ///                     "reference": { "width": 360, "height": 640 },
    ///                     "curve": { "type": "power", "exponent": 0.8 },
    ///                     "clamp": { "min": 0.85, "max": 1.6 },
    ///                     "rules": [ { "when": { "device": ["tablet"] },
    ///                                  "set": { "curve": { "type": "logarithmic", "k": 0.4 } } } ] } ] }
    /// </code>
    /// </summary>
    public static class ScalingStrategyJson
    {
        public const int FormatVersion = 1;

        /// <summary>
        /// Decodes a document (<c>{"strategies": [...]}</c>), a single strategy object, or an array.
        /// <c>extends</c> may name another strategy of the same document, a registered strategy,
        /// a built-in (<c>scaled</c>, <c>power</c>, …) or a preset (<c>tabletFriendly</c>, …).
        /// </summary>
        public static ScalingStrategyDocument Decode(string json)
        {
            var root = new MiniJson(json).Parse();
            List<object?> items;
            string? defaultId = null;
            if (root is Dictionary<string, object?> map)
            {
                if (map.ContainsKey("strategies"))
                {
                    var version = map.TryGetValue("version", out var v) && v is double d ? (int)d : FormatVersion;
                    if (version > FormatVersion) throw new ArgumentException($"Unsupported strategies format version {version}");
                    items = List(map["strategies"], "strategies");
                    defaultId = map.TryGetValue("default", out var def) ? def as string : null;
                }
                else items = new List<object?> { map };
            }
            else if (root is List<object?> list) items = list;
            else throw new ArgumentException("Expected a JSON object or array");

            var raw = new Dictionary<string, Dictionary<string, object?>>();
            var order = new List<string>();
            for (var i = 0; i < items.Count; i++)
            {
                var obj = items[i] as Dictionary<string, object?> ?? throw new ArgumentException($"strategies[{i}] must be an object");
                var id = Get(obj, "id") as string ?? throw new ArgumentException($"strategies[{i}].id is required");
                if (raw.ContainsKey(id)) throw new ArgumentException($"Duplicate strategy id '{id}'");
                raw[id] = obj;
                order.Add(id);
            }

            var built = new Dictionary<string, ScalingStrategy>();
            ScalingStrategy Build(string id, List<string> stack)
            {
                if (built.TryGetValue(id, out var done)) return done;
                if (stack.Contains(id)) throw new ArgumentException($"Cyclic 'extends': {string.Join(" -> ", stack.Append(id))}");
                var obj = raw[id];
                var parentId = Get(obj, "extends") as string;
                ScalingConfig parent;
                if (parentId == null) parent = ScalingConfig.Default;
                else if (raw.ContainsKey(parentId)) parent = Build(parentId, stack.Append(id).ToList()).Config;
                else parent = (ScalingStrategies.Get(parentId)
                    ?? throw new ArgumentException($"'{id}' extends unknown strategy '{parentId}'")).Config;
                var strategy = new ScalingStrategy(id, ReadConfig(obj, parent, id));
                built[id] = strategy;
                return strategy;
            }

            var ordered = new Dictionary<string, ScalingStrategy>();
            foreach (var id in order) ordered[id] = Build(id, new List<string>());
            return new ScalingStrategyDocument(ordered, defaultId);
        }

        /// <summary>Decodes and returns the single (or first) strategy.</summary>
        public static ScalingStrategy DecodeStrategy(string json) =>
            Decode(json).Strategies.Values.FirstOrDefault() ?? throw new ArgumentException("No strategy in JSON");

        /// <summary>Encodes one strategy. Lambda curves/transforms cannot be encoded.</summary>
        public static string Encode(ScalingStrategy strategy)
        {
            var sb = new StringBuilder();
            WriteStrategy(sb, strategy.Id, strategy.Config);
            return sb.ToString();
        }

        /// <summary>Encodes a full document.</summary>
        public static string EncodeDocument(IEnumerable<ScalingStrategy> strategies, string? defaultId = null)
        {
            var sb = new StringBuilder();
            sb.Append("{\"version\":").Append(FormatVersion);
            if (defaultId != null) sb.Append(",\"default\":").Append(Quote(defaultId));
            sb.Append(",\"strategies\":[");
            var first = true;
            foreach (var s in strategies)
            {
                if (!first) sb.Append(',');
                first = false;
                WriteStrategy(sb, s.Id, s.Config);
            }
            return sb.Append("]}").ToString();
        }

        // ── decoding ────────────────────────────────────────────────────────

        private static object? Get(Dictionary<string, object?> obj, string key) => obj.TryGetValue(key, out var v) ? v : null;

        private static ScalingConfig ReadConfig(Dictionary<string, object?> obj, ScalingConfig parent, string path)
        {
            var cfg = parent.Apply(ReadPatch(obj, path));
            // Explicit nulls at the root reset inherited values.
            if (obj.TryGetValue("clamp", out var c) && c == null) cfg = cfg.WithFactorBounds(null, null);
            if (obj.TryGetValue("valueClamp", out var vc) && vc == null) cfg = cfg.WithValueBounds(null, null);
            if (obj.TryGetValue("formula", out var fm) && fm == null) cfg = cfg.WithFormula(null);
            var rules = new List<ScalingRule>(parent.Rules);
            var rawRules = Get(obj, "rules");
            if (rawRules != null)
            {
                var list = List(rawRules, path + ".rules");
                for (var i = 0; i < list.Count; i++)
                {
                    var rp = $"{path}.rules[{i}]";
                    var rule = list[i] as Dictionary<string, object?> ?? throw new ArgumentException($"{rp} must be an object");
                    var when = Get(rule, "when") as Dictionary<string, object?> ?? new Dictionary<string, object?>();
                    var set = Get(rule, "set") as Dictionary<string, object?> ?? throw new ArgumentException($"{rp}.set is required");
                    rules.Add(new ScalingRule(ReadCondition(when, rp + ".when"), ReadPatch(set, rp + ".set"), Get(rule, "name") as string));
                }
            }
            return cfg.WithRules(rules);
        }

        private static ScalingPatch ReadPatch(Dictionary<string, object?> obj, string path)
        {
            var clamp = Get(obj, "clamp") as Dictionary<string, object?>;
            var valueClamp = Get(obj, "valueClamp") as Dictionary<string, object?>;
            var ar = Get(obj, "aspectRatio");
            ReferenceScreen? reference = null;
            if (Get(obj, "reference") is Dictionary<string, object?> r)
                reference = new ReferenceScreen(Num(Get(r, "width"), path + ".reference.width") ?? 300f,
                    Num(Get(r, "height"), path + ".reference.height") ?? 533f);
            bool? aspect;
            switch (ar)
            {
                case null: aspect = null; break;
                case bool b: aspect = b; break;
                case Dictionary<string, object?> m: aspect = Get(m, "enabled") as bool? ?? true; break;
                default: throw new ArgumentException($"{path}.aspectRatio must be a boolean or object");
            }
            var sensitivity = ar is Dictionary<string, object?> arMap
                ? Num(Get(arMap, "sensitivity"), path + ".aspectRatio.sensitivity") ?? Num(Get(obj, "sensitivity"), path + ".sensitivity")
                : Num(Get(obj, "sensitivity"), path + ".sensitivity");
            var axis = Get(obj, "axis") as string;
            var curve = Get(obj, "curve");
            var fontScale = Get(obj, "fontScale");
            Formula? formula = null;
            switch (Get(obj, "formula"))
            {
                case null: break;
                case string src: formula = Wrap(path + ".formula", () => new Formula(src)); break;
                default: throw new ArgumentException($"{path}.formula must be a string");
            }
            return new ScalingPatch(
                reference: reference,
                axis: axis == null ? (ScalingAxis?)null : CustomNames.AxisFromJson(axis),
                curve: curve == null ? null : ReadCurve(curve, path + ".curve"),
                multiplier: Num(Get(obj, "multiplier"), path + ".multiplier"),
                minFactor: clamp == null ? null : Num(Get(clamp, "min"), path + ".clamp.min"),
                maxFactor: clamp == null ? null : Num(Get(clamp, "max"), path + ".clamp.max"),
                minValue: valueClamp == null ? null : Num(Get(valueClamp, "min"), path + ".valueClamp.min"),
                maxValue: valueClamp == null ? null : Num(Get(valueClamp, "max"), path + ".valueClamp.max"),
                aspectRatio: aspect,
                sensitivity: sensitivity,
                fontScale: fontScale == null ? null : ReadFontScale(fontScale, path + ".fontScale"),
                ignoreMultiWindow: Get(obj, "ignoreMultiWindow") as bool?,
                formula: formula);
        }

        private static T Wrap<T>(string path, Func<T> create)
        {
            try { return create(); }
            catch (ArgumentException e) { throw new ArgumentException($"{path}: {e.Message}", e); }
        }

        private static ScalingCurve ReadCurve(object value, string path)
        {
            if (value is string s) return ReadCurve(new Dictionary<string, object?> { ["type"] = s }, path);
            var obj = value as Dictionary<string, object?> ?? throw new ArgumentException($"{path} must be an object or string");
            var type = Get(obj, "type") as string ?? throw new ArgumentException($"{path}.type is required");
            switch (type)
            {
                case "linear": return ScalingCurve.Linear;
                case "power": return ScalingCurve.Power(Num(Get(obj, "exponent"), path + ".exponent") ?? 0.75f);
                case "logarithmic": return ScalingCurve.Logarithmic(Num(Get(obj, "k"), path + ".k") ?? 0.4f);
                case "interpolated": return ScalingCurve.Interpolated(Num(Get(obj, "t"), path + ".t") ?? 0.5f);
                case "constant": return ScalingCurve.Constant(Num(Get(obj, "factor"), path + ".factor") ?? 1f);
                case "expression":
                    var src = Get(obj, "expression") as string ?? throw new ArgumentException($"{path}.expression is required");
                    return Wrap(path + ".expression", () => ScalingCurve.Expression(src));
                case "breakpoints":
                    var points = List(Get(obj, "points"), path + ".points");
                    return ScalingCurve.Breakpoints(points.Select((p, i) =>
                    {
                        var pp = $"{path}.points[{i}]";
                        var point = p as Dictionary<string, object?> ?? throw new ArgumentException($"{pp} must be an object");
                        return new Breakpoint(
                            Num(Get(point, "at"), pp + ".at") ?? throw new ArgumentException($"{pp}.at is required"),
                            Num(Get(point, "factor"), pp + ".factor") ?? throw new ArgumentException($"{pp}.factor is required"));
                    }).ToList());
                default:
                    throw new ArgumentException($"{path}.type '{type}' is not one of linear, power, logarithmic, interpolated, constant, breakpoints, expression");
            }
        }

        private static FontScalePolicy ReadFontScale(object value, string path)
        {
            if (value is string s && s == "follow") return FontScalePolicy.Follow;
            if (value is string s2 && s2 == "ignore") return FontScalePolicy.Ignore;
            if (value is Dictionary<string, object?> m)
                return FontScalePolicy.Clamp(Num(Get(m, "max"), path + ".max") ?? throw new ArgumentException($"{path}.max is required"));
            throw new ArgumentException($"{path} must be \"follow\", \"ignore\" or {{\"max\": n}}");
        }

        private static ScreenCondition ReadCondition(Dictionary<string, object?> obj, string path)
        {
            (float?, float?) Range(string key)
            {
                if (!(Get(obj, key) is Dictionary<string, object?> r)) return (null, null);
                return (Num(Get(r, "min"), $"{path}.{key}.min"), Num(Get(r, "max"), $"{path}.{key}.max"));
            }

            IEnumerable<DeviceClass>? devices;
            switch (Get(obj, "device"))
            {
                case null: devices = null; break;
                case string d: devices = new[] { CustomNames.DeviceFromJson(d) }; break;
                case List<object?> l:
                    devices = l.Select(x => CustomNames.DeviceFromJson(x as string ?? throw new ArgumentException($"{path}.device entries must be strings"))).ToList();
                    break;
                default: throw new ArgumentException($"{path}.device must be a string or array");
            }
            bool? landscape;
            switch (Get(obj, "orientation") as string)
            {
                case null: landscape = null; break;
                case "portrait": landscape = false; break;
                case "landscape": landscape = true; break;
                case var o: throw new ArgumentException($"{path}.orientation '{o}' must be portrait or landscape");
            }
            var sw = Range("smallestWidth");
            var w = Range("width");
            var h = Range("height");
            var ar = Range("aspectRatio");
            return new ScreenCondition(devices, landscape, sw.Item1, sw.Item2, w.Item1, w.Item2, h.Item1, h.Item2,
                ar.Item1, ar.Item2, Get(obj, "multiWindow") as bool?);
        }

        private static float? Num(object? v, string path)
        {
            switch (v)
            {
                case null: return null;
                case double d:
                    var f = (float)d;
                    if (!float.IsFinite(f)) throw new ArgumentException($"{path} must be finite");
                    return f;
                default: throw new ArgumentException($"{path} must be a number");
            }
        }

        private static List<object?> List(object? v, string path) =>
            v as List<object?> ?? throw new ArgumentException($"{path} must be an array");

        // ── encoding ────────────────────────────────────────────────────────

        private static void WriteStrategy(StringBuilder sb, string id, ScalingConfig c)
        {
            sb.Append("{\"id\":").Append(Quote(id));
            WritePatchFields(sb, new ScalingPatch(c.Reference, c.Axis, c.Curve, c.Multiplier, c.MinFactor, c.MaxFactor,
                c.MinValue, c.MaxValue, c.AspectRatio, c.Sensitivity, c.FontScale, c.IgnoreMultiWindow, c.Transform, c.Formula), defaults: true);
            if (c.Rules.Count > 0)
            {
                sb.Append(",\"rules\":[");
                for (var i = 0; i < c.Rules.Count; i++)
                {
                    var rule = c.Rules[i];
                    if (i > 0) sb.Append(',');
                    sb.Append('{');
                    if (rule.Name != null) sb.Append("\"name\":").Append(Quote(rule.Name)).Append(',');
                    sb.Append("\"when\":");
                    WriteCondition(sb, rule.Condition);
                    sb.Append(",\"set\":{");
                    var start = sb.Length;
                    WritePatchFields(sb, rule.Patch, defaults: false);
                    if (sb.Length > start && sb[start] == ',') sb.Remove(start, 1);
                    sb.Append("}}");
                }
                sb.Append(']');
            }
            sb.Append('}');
        }

        private static void WritePatchFields(StringBuilder sb, ScalingPatch p, bool defaults)
        {
            if (p.Transform != null) throw new InvalidOperationException("ValueTransform lambdas cannot be encoded to JSON");
            if (p.Reference != null && (!defaults || !p.Reference.Equals(ReferenceScreen.Default)))
                sb.Append(",\"reference\":{\"width\":").Append(N(p.Reference.Width)).Append(",\"height\":").Append(N(p.Reference.Height)).Append('}');
            if (p.Axis.HasValue && (!defaults || p.Axis.Value != ScalingAxis.SmallestWidth))
                sb.Append(",\"axis\":").Append(Quote(p.Axis.Value.JsonName()));
            if (p.Curve != null) { sb.Append(",\"curve\":"); WriteCurve(sb, p.Curve); }
            if (p.Multiplier.HasValue && (!defaults || p.Multiplier.Value != 1f)) sb.Append(",\"multiplier\":").Append(N(p.Multiplier.Value));
            if (p.MinFactor.HasValue || p.MaxFactor.HasValue) sb.Append(",\"clamp\":").Append(Range(p.MinFactor, p.MaxFactor));
            if (p.MinValue.HasValue || p.MaxValue.HasValue) sb.Append(",\"valueClamp\":").Append(Range(p.MinValue, p.MaxValue));
            if (p.AspectRatio.HasValue && (!defaults || p.AspectRatio.Value || p.Sensitivity.HasValue))
            {
                sb.Append(",\"aspectRatio\":{\"enabled\":").Append(p.AspectRatio.Value ? "true" : "false");
                if (p.Sensitivity.HasValue) sb.Append(",\"sensitivity\":").Append(N(p.Sensitivity.Value));
                sb.Append('}');
            }
            if (p.FontScale != null && (!defaults || p.FontScale != FontScalePolicy.Follow))
            {
                sb.Append(",\"fontScale\":");
                if (p.FontScale == FontScalePolicy.Follow) sb.Append("\"follow\"");
                else if (p.FontScale == FontScalePolicy.Ignore) sb.Append("\"ignore\"");
                else sb.Append("{\"max\":").Append(N(((ClampPolicy)p.FontScale).Max)).Append('}');
            }
            if (p.IgnoreMultiWindow.HasValue && (!defaults || p.IgnoreMultiWindow.Value))
                sb.Append(",\"ignoreMultiWindow\":").Append(p.IgnoreMultiWindow.Value ? "true" : "false");
            if (p.Formula != null) sb.Append(",\"formula\":").Append(Quote(p.Formula.Expression.Source));
        }

        private static void WriteCurve(StringBuilder sb, ScalingCurve c)
        {
            switch (c)
            {
                case PowerCurve p: sb.Append("{\"type\":\"power\",\"exponent\":").Append(N(p.Exponent)).Append('}'); break;
                case LogarithmicCurve l: sb.Append("{\"type\":\"logarithmic\",\"k\":").Append(N(l.K)).Append('}'); break;
                case InterpolatedCurve t: sb.Append("{\"type\":\"interpolated\",\"t\":").Append(N(t.T)).Append('}'); break;
                case ConstantCurve k: sb.Append("{\"type\":\"constant\",\"factor\":").Append(N(k.Factor)).Append('}'); break;
                case BreakpointsCurve b:
                    sb.Append("{\"type\":\"breakpoints\",\"points\":[")
                      .Append(string.Join(",", b.Points.Select(x => "{\"at\":" + N(x.At) + ",\"factor\":" + N(x.Factor) + "}")))
                      .Append("]}");
                    break;
                case ExpressionCurve x: sb.Append("{\"type\":\"expression\",\"expression\":").Append(Quote(x.Body.Source)).Append('}'); break;
                case CustomCurve _: throw new InvalidOperationException("Custom curve lambdas cannot be encoded to JSON");
                default: sb.Append("{\"type\":\"linear\"}"); break;
            }
        }

        private static void WriteCondition(StringBuilder sb, ScreenCondition c)
        {
            var parts = new List<string>();
            if (c.Devices != null)
                parts.Add("\"device\":[" + string.Join(",", c.Devices.OrderBy(d => (int)d).Select(d => Quote(d.JsonName()))) + "]");
            if (c.Landscape.HasValue) parts.Add(c.Landscape.Value ? "\"orientation\":\"landscape\"" : "\"orientation\":\"portrait\"");
            if (c.MinSmallestWidth.HasValue || c.MaxSmallestWidth.HasValue) parts.Add("\"smallestWidth\":" + Range(c.MinSmallestWidth, c.MaxSmallestWidth));
            if (c.MinWidth.HasValue || c.MaxWidth.HasValue) parts.Add("\"width\":" + Range(c.MinWidth, c.MaxWidth));
            if (c.MinHeight.HasValue || c.MaxHeight.HasValue) parts.Add("\"height\":" + Range(c.MinHeight, c.MaxHeight));
            if (c.MinAspectRatio.HasValue || c.MaxAspectRatio.HasValue) parts.Add("\"aspectRatio\":" + Range(c.MinAspectRatio, c.MaxAspectRatio));
            if (c.MultiWindow.HasValue) parts.Add("\"multiWindow\":" + (c.MultiWindow.Value ? "true" : "false"));
            sb.Append('{').Append(string.Join(",", parts)).Append('}');
        }

        private static string Range(float? min, float? max)
        {
            var parts = new List<string>(2);
            if (min.HasValue) parts.Add("\"min\":" + N(min.Value));
            if (max.HasValue) parts.Add("\"max\":" + N(max.Value));
            return "{" + string.Join(",", parts) + "}";
        }

        private static string N(float v) => v.ToString("R", CultureInfo.InvariantCulture);

        internal static string Quote(string s)
        {
            var sb = new StringBuilder(s.Length + 2).Append('"');
            foreach (var ch in s)
            {
                switch (ch)
                {
                    case '"': sb.Append("\\\""); break;
                    case '\\': sb.Append("\\\\"); break;
                    case '\n': sb.Append("\\n"); break;
                    case '\r': sb.Append("\\r"); break;
                    case '\t': sb.Append("\\t"); break;
                    default:
                        if (ch < ' ') sb.Append("\\u").Append(((int)ch).ToString("x4", CultureInfo.InvariantCulture));
                        else sb.Append(ch);
                        break;
                }
            }
            return sb.Append('"').ToString();
        }
    }

    /// <summary>
    /// Minimal RFC 8259 parser → <c>Dictionary&lt;string, object?&gt;</c> / <c>List&lt;object?&gt;</c> /
    /// <c>string</c> / <c>double</c> / <c>bool</c> / <c>null</c>.
    /// </summary>
    public sealed class MiniJson
    {
        private readonly string _src;
        private int _i;

        public MiniJson(string src) { _src = src ?? throw new ArgumentNullException(nameof(src)); }

        public object? Parse()
        {
            var v = Value();
            Ws();
            if (_i != _src.Length) Fail("Unexpected trailing content");
            return v;
        }

        private object? Value()
        {
            Ws();
            if (_i >= _src.Length) Fail("Unexpected end of JSON");
            var c = _src[_i];
            switch (c)
            {
                case '{': return Obj();
                case '[': return Arr();
                case '"': return Str();
                case 't': return Lit("true", true);
                case 'f': return Lit("false", false);
                case 'n': return Lit("null", null);
                default:
                    if (c == '-' || char.IsDigit(c)) return Num();
                    Fail($"Unexpected character '{c}'");
                    return null;
            }
        }

        private Dictionary<string, object?> Obj()
        {
            var output = new Dictionary<string, object?>();
            _i++;
            Ws();
            if (Peek() == '}') { _i++; return output; }
            while (true)
            {
                Ws();
                if (Peek() != '"') Fail("Expected a string key");
                var k = Str();
                Ws();
                Expect(':');
                output[k] = Value();
                Ws();
                switch (Peek())
                {
                    case ',': _i++; break;
                    case '}': _i++; return output;
                    default: Fail("Expected ',' or '}'"); break;
                }
            }
        }

        private List<object?> Arr()
        {
            var output = new List<object?>();
            _i++;
            Ws();
            if (Peek() == ']') { _i++; return output; }
            while (true)
            {
                output.Add(Value());
                Ws();
                switch (Peek())
                {
                    case ',': _i++; break;
                    case ']': _i++; return output;
                    default: Fail("Expected ',' or ']'"); break;
                }
            }
        }

        private string Str()
        {
            _i++;
            var sb = new StringBuilder();
            while (true)
            {
                if (_i >= _src.Length) Fail("Unterminated string");
                var c = _src[_i++];
                if (c == '"') return sb.ToString();
                if (c != '\\') { sb.Append(c); continue; }
                if (_i >= _src.Length) Fail("Unterminated escape");
                var e = _src[_i++];
                switch (e)
                {
                    case '"': case '\\': case '/': sb.Append(e); break;
                    case 'b': sb.Append('\b'); break;
                    case 'f': sb.Append('\f'); break;
                    case 'n': sb.Append('\n'); break;
                    case 'r': sb.Append('\r'); break;
                    case 't': sb.Append('\t'); break;
                    case 'u':
                        if (_i + 4 > _src.Length) Fail("Bad unicode escape");
                        sb.Append((char)int.Parse(_src.Substring(_i, 4), NumberStyles.HexNumber, CultureInfo.InvariantCulture));
                        _i += 4;
                        break;
                    default: Fail($"Bad escape '\\{e}'"); break;
                }
            }
        }

        private double Num()
        {
            var start = _i;
            if (Peek() == '-') _i++;
            while (_i < _src.Length && (char.IsDigit(_src[_i]) || ".eE+-".IndexOf(_src[_i]) >= 0)) _i++;
            var text = _src.Substring(start, _i - start);
            if (!double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var d)) Fail($"Bad number '{text}'");
            return d;
        }

        private object? Lit(string word, object? v)
        {
            if (string.CompareOrdinal(_src, _i, word, 0, word.Length) != 0) Fail($"Expected '{word}'");
            _i += word.Length;
            return v;
        }

        private void Ws()
        {
            while (_i < _src.Length && char.IsWhiteSpace(_src[_i])) _i++;
        }

        private char Peek() => _i < _src.Length ? _src[_i] : '\0';

        private void Expect(char c)
        {
            if (Peek() != c) Fail($"Expected '{c}'");
            _i++;
        }

        private void Fail(string msg) => throw new ArgumentException($"Invalid JSON at {_i}: {msg}");
    }
}
